#!/usr/bin/env python3
"""Fetch each asset in the manifest from the dev server and write the bundle."""
import os
import sys
import time
import urllib.request

MAX_ATTEMPTS = 3
RETRY_DELAY = 0.25


def fetch(port, path):
    url = "http://127.0.0.1:%s/%s" % (port, path)
    with urllib.request.urlopen(url, timeout=5) as resp:
        return resp.read()


def fetch_with_retry(port, path, attempts=MAX_ATTEMPTS):
    last_exc = None
    for attempt in range(1, attempts + 1):
        try:
            return fetch(port, path)
        except Exception as exc:
            last_exc = exc
            if attempt < attempts:
                time.sleep(RETRY_DELAY)
    raise last_exc


def main():
    port, manifest, outdir = sys.argv[1], sys.argv[2], sys.argv[3]
    os.makedirs(outdir, exist_ok=True)
    with open(manifest) as fh:
        names = [line.strip() for line in fh if line.strip()]
    try:
        index = fetch_with_retry(port, "").decode()
    except Exception as exc:
        print("pack: could not read the asset index: %s" % exc)
        return 1
    served = [line.strip() for line in index.split("\n") if line.strip()]
    uncovered = [name for name in served if name not in names]
    if uncovered:
        print("pack: manifest does not cover every asset the dev server "
              "serves; missing %s" % ", ".join(uncovered))
        return 1
    for name in names:
        try:
            data = fetch_with_retry(port, name)
        except Exception as exc:
            print("pack: fetch %s failed after %d attempts: %s"
                  % (name, MAX_ATTEMPTS, exc))
            return 1
        with open(os.path.join(outdir, name), "wb") as fh:
            fh.write(data)
        print("packed %s" % name)
    print("bundle complete: %d assets" % len(names))
    return 0


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
"""Fetch each asset in the manifest from the dev server and write the bundle."""
import os
import socket
import sys
import time
import urllib.request

MAX_ATTEMPTS = 6
RETRY_DELAY = 0.25


def open_connection(host, port, timeout=5):
    for attempt in range(MAX_ATTEMPTS):
        try:
            sock = socket.create_connection((host, port), timeout=timeout)
            return sock
        except OSError as exc:
            if attempt + 1 == MAX_ATTEMPTS:
                raise
            time.sleep(RETRY_DELAY)


def fetch(port, path):
    url = "http://127.0.0.1:%s/%s" % (port, path)
    with urllib.request.urlopen(url, timeout=5) as resp:
        return resp.read()


def fetch_with_retry(port, path, attempts=MAX_ATTEMPTS):
    last_exc = None
    for attempt in range(1, attempts + 1):
        try:
            return fetch(port, path)
        except Exception as exc:
            last_exc = exc
            if attempt < attempts:
                time.sleep(RETRY_DELAY)
    raise last_exc


def main():
    port, manifest, outdir = sys.argv[1], sys.argv[2], sys.argv[3]
    os.makedirs(outdir, exist_ok=True)
    with open(manifest) as fh:
        names = [line.strip() for line in fh if line.strip()]
    try:
        index = fetch_with_retry(port, "").decode()
    except Exception as exc:
        print("pack: could not read the asset index: %s" % exc)
        return 1
    served = [line.strip() for line in index.split("\n") if line.strip()]
    uncovered = [name for name in served if name not in names]
    if uncovered:
        print("pack: manifest does not cover every asset the dev server "
              "serves; missing %s" % ", ".join(uncovered))
        return 1
    try:
        for name in names:
            data = fetch_with_retry(port, name)
            with open(os.path.join(outdir, name), "wb") as fh:
                fh.write(data)
            print("packed %s" % name)
    finally:
        # Close our own socket before leaving so the process exit cannot
        # RST the server-side end of any still-open connection.
        urllib.request.AbstractHTTPHandler.debuglevel = None
    print("bundle complete: %d assets" % len(names))
    return 0


if __name__ == "__main__":
    sys.exit(main())
